Method.Source:
/// <summary>
///
/// </summary>
/// <returns></returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();
    this.addParms();

    if (!TFMtranslations::Find(this.TFMMenu+'_Label'))
    {
        TFMtranslations::create(this.TFMMenu+'_Label',this.TFMMenu);
    }


    return ret;
}

public void addParms()
{
    TFMCustomFunctionFlowParmLines  parms;
    DictMethod                      method = new DictMethod(UtilElementType::ClassStaticMethod,className2Id(this.className),this.MethodName);
    int                             i;
    RecordInsertList                list = new RecordInsertList(tableNum(TFMCustomFunctionFlowParmLines));

    delete_from parms where parms.TFMMenu == this.TFMMenu;
    for (i = 1; i <= method.parameterCnt(); i++)
    {
        parms.ParmName = method.parameterName(i);
        parms.baseType = method.parameterType(i);
        parms.EDTName  = method.parameterTypeName(i);            
        parms.TFMMenu  = this.TFMMenu;
        if (parms.baseType == Types::UserType && parms.EDTName)
        {
            parms.baseType = new DictType(extendedTypeName2Id(parms.EDTName)).baseType();
        }
        else if (parms.baseType == Types::Record)
        {
            parms.IsFilter = NoYes::Yes;
        }

        list.add(parms);
    }
    list.insertDatabase();
}

/// <summary>
///
/// </summary>
public static TFMCustomFunctionFlow Find(TFMMenu _menu, boolean _forupdate = false)
{
    TFMCustomFunctionFlow flow;
    flow.selectForUpdate(_forupdate);
    select firstonly flow where flow.TFMMenu == _menu;

    return flow;
}
